		log.Fatalf("连接 MySQL 失败: %v", err)
	}
	if err := DB.AutoMigrate(&User{}, &Wish{}, &TasteResponse{}, &CoinTransaction{}); err != nil {
		log.Fatalf("自动迁移失败: %v", err)
	}
	log.Println("MySQL 连接成功，数据表已就绪")
}

