$ErrorActionPreference = "Stop"
$B = "http://localhost:8080/api"
function Call($path, $token, $bodyObj) {
  $headers = @{ }
  if ($token) { $headers["Authorization"] = "Bearer $token" }
  try {
    if ($null -ne $bodyObj) {
      $json = $bodyObj | ConvertTo-Json -Depth 6
      $bytes = [System.Text.Encoding]::UTF8.GetBytes($json)
      return Invoke-RestMethod -Uri "$B$path" -Method Post -Headers $headers -ContentType "application/json; charset=utf-8" -Body $bytes
    } else {
      return Invoke-RestMethod -Uri "$B$path" -Method Get -Headers $headers
    }
  } catch {
    $resp = $_.Exception.Response
    $code = if ($resp) { [int]$resp.StatusCode } else { 0 }
    $msg = ""
    if ($resp) {
      $sr = New-Object System.IO.StreamReader($resp.GetResponseStream())
      $msg = ($sr.ReadToEnd() | ConvertFrom-Json).error
    }
    return @{ __error = $true; code = $code; error = $msg }
  }
}

$ali = Call "/login" $null @{ username = "ali"; password = "123456" }
$bo  = Call "/login" $null @{ username = "bo";  password = "123456" }
$ta = $ali.token; $tb = $bo.token
Write-Host "1. 初始  ali coins=$($ali.user.coins) frozen=$($ali.user.frozen_coins) | bo coins=$($bo.user.coins) frozen=$($bo.user.frozen_coins)"

$w = Call "/wishes" $ta @{ restaurant_name="测试豆花店"; address="测试路1号"; dish_list="咸豆花、甜豆花"; reason="想知道咸甜豆花哪个更绝"; reward_coins=25 }
if ($w.__error) { Write-Host "发帖失败: $($w.error)"; exit 1 }
$wid = $w.wish.id
$me = Call "/me" $ta
Write-Host "2. 冻结25后 ali coins=$($me.user.coins) frozen=$($me.user.frozen_coins)  (期望 45 / 25)"

$w2 = Call "/wishes/$wid/append" $ta @{ amount=10 }
$me = Call "/me" $ta
Write-Host "3. 追加10后 悬赏=$($w2.wish.reward_coins) wish冻结=$($w2.wish.frozen_coins) | ali coins=$($me.user.coins) frozen=$($me.user.frozen_coins)  (期望 35/35)"

$r = Call "/wishes/$wid/responses" $tb @{ photos=@("/uploads/seed/cake.svg"); comment="咸豆花鲜滑带虾皮，甜豆花桂花糖水香，两碗都喝光啦！"; rating=5 }
$rid = $r.response.id
Write-Host "4. bo 代吃成功 response id=$rid"

$dup = Call "/wishes/$wid/responses" $tb @{ photos=@("/uploads/seed/cake.svg"); comment="重复提交的点评内容要有五个字以上"; rating=4 }
Write-Host "5. 重复代吃 -> HTTP $($dup.code): $($dup.error)"
$self = Call "/wishes/$wid/responses" $ta @{ photos=@("/uploads/seed/cake.svg"); comment="自己替自己吃应该被拒绝掉哦"; rating=3 }
Write-Host "6. 自己代吃 -> HTTP $($self.code): $($self.error)"

$ok = Call "/wishes/$wid/settle" $ta @{ response_id=$rid }
$ma = Call "/me" $ta; $mb = Call "/me" $tb
Write-Host "7. 结算: $($ok.message)"
Write-Host "   ali coins=$($ma.user.coins) frozen=$($ma.user.frozen_coins) (期望35/0) | bo coins=$($mb.user.coins) frozen=$($mb.user.frozen_coins) (期望145/0)"

$again = Call "/wishes/$wid/settle" $ta @{ response_id=$rid }
Write-Host "8. 重复结算 -> HTTP $($again.code): $($again.error)"

$tx = Call "/my/transactions" $ta
$sum = ($tx.items | Measure-Object -Property amount -Sum).Sum
$statusTxn = if ($sum -eq $ma.user.coins) { "OK" } else { "MISMATCH" }
Write-Host "9. ali 流水合计=$sum 等于余额=$($ma.user.coins) -> $statusTxn"

$detail = Call "/wishes/$wid"
$marks = ($detail.wish.responses | ForEach-Object { "$($_.user.nickname):adopted=$($_.is_adopted)" }) -join ", "
Write-Host "10. 心愿状态=$($detail.wish.status) | $marks"

# 取消退款路径：再发一单后取消
$w3 = Call "/wishes" $ta @{ restaurant_name="待取消奶茶"; address="路口"; dish_list="手打柠檬茶"; reason="测试退款路径完整性"; reward_coins=12 }
$before = (Call "/me" $ta).user.coins
$cn = Call "/wishes/$($w3.wish.id)/cancel" $ta
$after = Call "/me" $ta
Write-Host "11. 取消退款: $($cn.message) 余额 $before -> $($after.user.coins) (期望+12)"
$cn2 = Call "/wishes/$($w3.wish.id)/cancel" $ta
Write-Host "12. 重复取消 -> HTTP $($cn2.code): $($cn2.error)"

