:root {
  /* 暖色美食主题：番茄红 + 暖橙 + 奶油底 */
  --brand: #e8552d;
  --brand-dark: #c73e1d;
  --brand-soft: #fff0e9;
  --accent: #f5a623;
  --ink: #2b2118;
  --ink-soft: #7a6a5c;
  --line: #f0e4d8;
  --card: #ffffff;
  --bg: #fdf8f3;
  --ok: #2f9e6e;
  --ok-soft: #e4f5ed;
  --warn: #b7791f;
  --warn-soft: #fdf2dd;
  --shadow: 0 10px 30px rgba(180, 90, 40, 0.12);
  --radius: 18px;
}

* { box-sizing: border-box; }

html, body, #app {
  margin: 0;
  padding: 0;
  min-height: 100%;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'PingFang SC',
    'Hiragino Sans GB', 'Microsoft YaHei', sans-serif;
  color: var(--ink);
  background: var(--bg);
  -webkit-font-smoothing: antialiased;
}

a { color: inherit; text-decoration: none; }
button { font-family: inherit; }

.container {
  max-width: 880px;
  margin: 0 auto;
  padding: 0 16px 60px;
}

/* ---------- 通用按钮 ---------- */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  border: none;
  border-radius: 999px;
  padding: 10px 20px;
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
  transition: transform 0.12s ease, box-shadow 0.12s ease, background 0.2s;
  white-space: nowrap;
}
.btn:active { transform: scale(0.97); }
.btn-primary {
  background: linear-gradient(135deg, var(--brand), var(--brand-dark));
  color: #fff;
  box-shadow: 0 6px 16px rgba(232, 85, 45, 0.32);
}
.btn-primary:hover { box-shadow: 0 8px 20px rgba(232, 85, 45, 0.42); }
.btn-primary:disabled {
  background: #e7d6cb;
  box-shadow: none;
  cursor: not-allowed;
}
.btn-ghost {
  background: var(--brand-soft);
  color: var(--brand-dark);
}
.btn-ghost:hover { background: #ffe1d3; }
.btn-plain {
  background: transparent;
  color: var(--ink-soft);
  border: 1px solid var(--line);
}
.btn-plain:hover { border-color: var(--brand); color: var(--brand); }
.btn-sm { padding: 6px 14px; font-size: 13px; }
.btn-block { width: 100%; }

/* ---------- 标签 / 徽章 ---------- */
.tag {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 3px 10px;
  border-radius: 999px;
  font-size: 12px;
  font-weight: 600;
}
.tag-open { background: var(--warn-soft); color: var(--warn); }
.tag-settled { background: var(--ok-soft); color: var(--ok); }
.tag-canceled { background: #f1ece7; color: #9b8c7e; }

.coin {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-weight: 800;
  color: #b8641a;
}
.coin::before { content: '🪙'; font-size: 0.95em; }

/* ---------- 表单 ---------- */
.field { margin-bottom: 16px; }
.field label {
  display: block;
  font-size: 13px;
  font-weight: 700;
  margin-bottom: 6px;
  color: var(--ink);
}
.field input,
.field textarea,
.field select {
  width: 100%;
  border: 1.5px solid var(--line);
  border-radius: 12px;
  padding: 11px 14px;
  font-size: 14px;
  font-family: inherit;
  color: var(--ink);
  background: #fff;
  outline: none;
  transition: border-color 0.15s;
}
.field input:focus,
.field textarea:focus { border-color: var(--brand); }
.field textarea { resize: vertical; min-height: 80px; }
.field .hint { font-size: 12px; color: var(--ink-soft); margin-top: 4px; }

/* ---------- 弹层 ---------- */
.modal-mask {
  position: fixed;
  inset: 0;
  background: rgba(43, 33, 24, 0.45);
  display: flex;
  align-items: flex-end;
  justify-content: center;
  z-index: 100;
  padding: 0;
}
@media (min-width: 640px) {
  .modal-mask { align-items: center; padding: 20px; }
}
.modal {
  background: var(--card);
  width: 100%;
  max-width: 560px;
  max-height: 92vh;
  overflow-y: auto;
  border-radius: 24px 24px 0 0;
  padding: 24px 22px 28px;
  animation: sheet-up 0.25s ease;
}
@media (min-width: 640px) {
  .modal { border-radius: 24px; }
}
@keyframes sheet-up {
  from { transform: translateY(40px); opacity: 0.6; }
  to { transform: translateY(0); opacity: 1; }
}
.modal h3 { margin: 0 0 18px; font-size: 19px; }
.modal-close {
  float: right;
  border: none;
  background: #f6ede5;
  width: 32px;
  height: 32px;
  border-radius: 50%;
  font-size: 16px;
  cursor: pointer;
  color: var(--ink-soft);
}

/* ---------- 轻提示 ---------- */
.toast {
  position: fixed;
  left: 50%;
  bottom: 84px;
  transform: translateX(-50%);
  background: rgba(43, 33, 24, 0.92);
  color: #fff;
  padding: 11px 22px;
  border-radius: 999px;
  font-size: 14px;
  z-index: 200;
  animation: toast-in 0.2s ease;
  max-width: 90vw;
  text-align: center;
}
.toast.ok { background: rgba(47, 158, 110, 0.95); }
.toast.err { background: rgba(210, 60, 40, 0.95); }
@keyframes toast-in {
  from { opacity: 0; transform: translate(-50%, 10px); }
  to { opacity: 1; transform: translate(-50%, 0); }
}

.empty {
  text-align: center;
  color: var(--ink-soft);
  padding: 60px 20px;
}
.empty .emoji { font-size: 48px; display: block; margin-bottom: 12px; }

.muted { color: var(--ink-soft); }
.small { font-size: 12px; }

