// 通过 CDP 找出撑宽页面的元素
const base = 'http://127.0.0.1:9333'
async function getWS() {
  const list = await (await fetch(base + '/json/new?http://127.0.0.1:5174/', { method: 'PUT' })).json().catch(async () => {
    // 某些版本不允许 PUT，改用列表
    return null
  })
  return list
}

async function main() {
  // 新建标签页并导航
  let tab
  try {
    tab = await (await fetch(base + '/json/new?http://127.0.0.1:5174/', { method: 'PUT' })).json()
  } catch (e) {
    const tabs = await (await fetch(base + '/json')).json()
    tab = tabs[0]
  }
  const ws = new WebSocket(tab.webSocketDebuggerUrl)
  await new Promise((r) => (ws.onopen = r))
  let id = 0
  const pending = new Map()
  ws.onmessage = (e) => {
    const m = JSON.parse(e.data)
    if (m.id && pending.has(m.id)) pending.get(m.id)(m)
  }
  const send = (method, params = {}) =>
    new Promise((res) => {
      const mid = ++id
      pending.set(mid, res)
      ws.send(JSON.stringify({ id: mid, method, params }))
    })

  await send('Page.enable')
  await send('Runtime.enable')
  await send('Emulation.setDeviceMetricsOverride', {
    width: 430, height: 900, deviceScaleFactor: 1, mobile: true
  })
  await new Promise((r) => setTimeout(r, 3500))

  const expr = `(() => {
    const vw = document.documentElement.clientWidth;
    const docW = document.documentElement.scrollWidth;
    const bodyW = document.body.scrollWidth;
    const offenders = [];
    document.querySelectorAll('*').forEach(el => {
      const r = el.getBoundingClientRect();
      if (r.right > vw + 1 && r.width > 0) {
        offenders.push({
          tag: el.tagName,
          cls: (el.className && el.className.toString) ? el.className.toString().slice(0,60) : '',
          left: Math.round(r.left), right: Math.round(r.right), width: Math.round(r.width)
        });
      }
    });
    // 只保留最外层（right 最大的若干个）
    offenders.sort((a,b) => b.right - a.right);
    return JSON.stringify({ vw, docW, bodyW, top: offenders.slice(0, 12) }, null, 1);
  })()`

  const r = await send('Runtime.evaluate', { expression: expr, returnByValue: true })
  console.log(r.result.result.value)
  ws.close()
  process.exit(0)
}
main().catch((e) => { console.error(e); process.exit(1) })

