// 测量卡片内部几何，定位右侧裁切根因
const base = 'http://127.0.0.1:9333'

async function main() {
  let tab
  try {
    tab = await (await fetch(base + '/json/new?http://127.0.0.1:5174/', { method: 'PUT' })).json()
  } catch (e) {
    const tabs = await (await fetch(base + '/json')).json()
    tab = tabs.find((t) => t.url.includes('5174')) || tabs[0]
  }
  const ws = new WebSocket(tab.webSocketDebuggerUrl)
  await new Promise((r) => (ws.onopen = r))
  let id = 0
  const pending = new Map()
  ws.onmessage = (e) => {
    const m = JSON.parse(e.data)
    if (m.id && pending.has(m.id)) pending.get(m.id)(m)
  }
  const send = (method, params = {}) =>
    new Promise((res) => {
      const mid = ++id
      pending.set(mid, res)
      ws.send(JSON.stringify({ id: mid, method, params }))
    })

  await send('Page.enable')
  await send('Runtime.enable')
  await send('Emulation.setDeviceMetricsOverride', { width: 430, height: 1400, deviceScaleFactor: 1, mobile: true })
  await send('Page.navigate', { url: 'http://127.0.0.1:5174/' })
  await new Promise((r) => setTimeout(r, 4000))

  const expr = `(() => {
    const pick = (sel, root=document) => {
      const el = root.querySelector(sel);
      if (!el) return null;
      const r = el.getBoundingClientRect();
      const cs = getComputedStyle(el);
      return { sel, left: Math.round(r.left), right: Math.round(r.right),
               width: Math.round(r.width), padL: cs.paddingLeft, padR: cs.paddingRight,
               box: cs.boxSizing, pos: cs.position };
    };
    const card = document.querySelector('.card-wrap');
    const out = {
      main: pick('.app-main'),
      card: pick('.card-wrap'),
      scene: pick('.flip-scene'),
      inner: pick('.flip-inner'),
      front: pick('.face-front'),
      head: pick('.front-head'),
      who: pick('.who'),
      tag: card ? pick('.tag', card) : null,
      foot: pick('.front-foot'),
      actions: pick('.front-actions'),
      hint: pick('.resp-hint'),
      flipbtn: pick('.flip-btn')
    };
    return JSON.stringify(out, null, 1);
  })()`

  const r = await send('Runtime.evaluate', { expression: expr, returnByValue: true })
  console.log(r.result.result.value)
  ws.close()
  process.exit(0)
}
main().catch((e) => { console.error(e); process.exit(1) })

