// 用法: node cdp-run.mjs <url> <out.png> <width> <height> <jsFile>
// 在页面加载后执行 jsFile 中的表达式（可 await），再截图
import { readFileSync, writeFileSync } from 'fs'
const base = 'http://127.0.0.1:9333'

const [url, out, widthS, heightS, jsFile] = process.argv.slice(2)
const width = Number(widthS || 430)
const height = Number(heightS || 1400)

async function main() {
  const tab = await (await fetch(base + '/json/new?about:blank', { method: 'PUT' })).json()
  const ws = new WebSocket(tab.webSocketDebuggerUrl)
  await new Promise((r) => (ws.onopen = r))
  let id = 0
  const pending = new Map()
  ws.onmessage = (e) => {
    const m = JSON.parse(e.data)
    if (m.id && pending.has(m.id)) pending.get(m.id)(m)
  }
  const send = (method, params = {}) =>
    new Promise((res) => {
      const mid = ++id
      pending.set(mid, res)
      ws.send(JSON.stringify({ id: mid, method, params }))
    })
  const evalJs = async (expression, awaitPromise = true) => {
    const r = await send('Runtime.evaluate', { expression, awaitPromise, returnByValue: true })
    if (r.result?.exceptionDetails) {
      console.log('JS EXCEPTION:', JSON.stringify(r.result.exceptionDetails.exception?.description || r.result.exceptionDetails.text))
    }
    return r.result?.result?.value
  }

  await send('Page.enable')
  await send('Emulation.setDeviceMetricsOverride', { width, height, deviceScaleFactor: 1, mobile: true })
  await send('Page.navigate', { url })
  await new Promise((r) => setTimeout(r, 4000))

  if (jsFile) {
    const code = readFileSync(jsFile, 'utf8')
    const wrapped = `(async () => { ${code} })()`
    await evalJs(wrapped)
    await new Promise((r) => setTimeout(r, 1200))
  }

  const { result } = await send('Page.captureScreenshot', { format: 'png' })
  writeFileSync(out, Buffer.from(result.data, 'base64'))
  console.log('saved', out)
  ws.close()
  process.exit(0)
}
main().catch((e) => { console.error(e); process.exit(1) })

